insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m1-03$L$, $L$Fundamentals of Testing$L$, 1, $L$K2$L$, null, null, $L$Which of the following is a typical objective of testing?$L$, $J$[{"text":"To prevent defects by evaluating work products such as requirements and user stories","correct":true,"why":"Reviewing requirements and designs early is a recognized test objective because it prevents defects from being built into later work products."},{"text":"To assign blame to the developers who introduced defects","correct":false,"why":"Assigning blame is not a test objective and contradicts the constructive, whole-team psychology of testing."},{"text":"To guarantee that the system will never fail in operation","correct":false,"why":"No test activity can guarantee a system never fails; testing reduces risk rather than eliminating it."},{"text":"To replace the need for requirements analysis entirely","correct":false,"why":"Testing complements analysis; it does not remove the need to define requirements."}]$J$::jsonb, $L$The syllabus lists typical test objectives including evaluating work products, preventing defects, finding failures, reducing risk, and verifying and validating the product. Preventing defects through early evaluation is one of these core objectives.$L$, $L$Before coding a mobile login screen, the QA team reviews the acceptance criteria and spots a missing account-lockout rule, preventing a defect before any code is written.$L$
