on conflict (course_id, ext_key) do update set
  syllabus_topic = excluded.syllabus_topic, module_number = excluded.module_number, k_level = excluded.k_level,
  mock = excluded.mock, mock_order = excluded.mock_order, question_text = excluded.question_text,
  options = excluded.options, explanation = excluded.explanation, workplace_example = excluded.workplace_example;

insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m1-04$L$, $L$Fundamentals of Testing$L$, 1, $L$K2$L$, null, null, $L$What is the key difference between testing and debugging?$L$, $J$[{"text":"Testing identifies failures caused by defects, while debugging finds, analyzes, and fixes those defects","correct":true,"why":"The syllabus distinguishes dynamic testing (which triggers failures) from debugging (locating the cause and correcting the defect)."},{"text":"Debugging identifies failures, while testing fixes the underlying code","correct":false,"why":"This reverses the two activities; fixing code is debugging, not testing."},{"text":"Testing and debugging are two names for the same activity","correct":false,"why":"They are distinct activities performed for different purposes and often by different roles."},{"text":"Debugging can only be done after all testing is fully complete","correct":false,"why":"Debugging happens whenever a failure is investigated, often interleaved with testing, not strictly afterward."}]$J$::jsonb, $L$According to Fundamentals of Testing, dynamic testing can show failures caused by defects, whereas debugging is the development activity that finds, analyzes, and removes the cause of those failures. Confirmation testing then checks that the fix resolved the failure.$L$, $L$A tester reports that a shopping cart shows the wrong total (a failure); a developer then debugs the pricing function, finds an incorrect tax calculation, and fixes it.$L$
