insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m1-07$L$, $L$Fundamentals of Testing$L$, 1, $L$K1$L$, null, null, $L$Which of the following is NOT one of the seven testing principles?$L$, $J$[{"text":"Exhaustive testing guarantees a defect-free product","correct":true,"why":"This is the opposite of the real principle, which states that exhaustive testing is impossible; so it is not a valid principle."},{"text":"Early testing saves time and money","correct":false,"why":"This is a genuine principle: finding defects early reduces the cost of fixing them."},{"text":"Defects cluster together","correct":false,"why":"This is a genuine principle: a small number of modules usually contain most defects."},{"text":"Testing is context dependent","correct":false,"why":"This is a genuine principle: testing is done differently depending on the context."}]$J$::jsonb, $L$The seven principles are: testing shows presence not absence of defects; exhaustive testing is impossible; early testing saves time and money; defects cluster together; tests wear out (the pesticide paradox); testing is context dependent; and absence-of-defects is a fallacy. A claim that exhaustive testing guarantees quality contradicts these.$L$, $L$A test manager for a mobile banking app prioritizes risk-based tests instead of trying every possible input combination, applying the principle that exhaustive testing is impossible.$L$
