insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m1-09$L$, $L$Fundamentals of Testing$L$, 1, $L$K2$L$, null, null, $L$Why does the principle early testing saves time and money hold true?$L$, $J$[{"text":"Defects found early, for example during requirements review, are cheaper to fix than those found in production","correct":true,"why":"The cost of fixing a defect rises the later it is found, so early static and dynamic testing reduces overall cost."},{"text":"Early testing means fewer testers are needed on the project","correct":false,"why":"The principle concerns defect-fix cost and timing, not staffing levels."},{"text":"Testing early proves the software has no defects","correct":false,"why":"No testing proves absence of defects; this confuses two separate ideas."},{"text":"Early testing removes the need for later test levels","correct":false,"why":"Early testing complements later levels such as system and acceptance testing; it does not replace them."}]$J$::jsonb, $L$Fundamentals of Testing teaches that starting test activities early, including static testing of requirements and designs, catches defects before they propagate. Because the cost of correcting a defect grows the later it is detected, early testing lowers total cost and rework.$L$, $L$Reviewing a payment API specification uncovers a missing timeout requirement; fixing the spec costs minutes, whereas catching it after go-live would mean an emergency production patch.$L$
