insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m1-10$L$, $L$Fundamentals of Testing$L$, 1, $L$K1$L$, null, null, $L$Which principle warns that a small number of modules typically contain most of the defects?$L$, $J$[{"text":"Defects cluster together","correct":true,"why":"Defect clustering states that a minority of components usually accounts for the majority of defects, guiding where to focus testing."},{"text":"Tests show the presence of defects, not their absence","correct":false,"why":"This principle concerns what a passing test can conclude, not the distribution of defects."},{"text":"Testing is context dependent","correct":false,"why":"This principle concerns adapting the approach to the situation, not defect distribution."},{"text":"The pesticide paradox","correct":false,"why":"This principle concerns the fading effectiveness of repeated tests, not where defects concentrate."}]$J$::jsonb, $L$The defect clustering principle observes that defects are not evenly spread; a small number of modules often contains most of them, frequently reflecting complexity or churn. Testers use this to focus effort where failures are most likely.$L$, $L$Analysis of a logistics system shows that 80 percent of production incidents trace to the route-optimization module, so testers concentrate additional scenarios there.$L$
