insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m1-11$L$, $L$Fundamentals of Testing$L$, 1, $L$K1$L$, null, null, $L$The test process includes several activities. Which activity is concerned with checking progress against the plan and taking corrective action?$L$, $J$[{"text":"Test monitoring and control","correct":true,"why":"Monitoring compares actual progress to the plan, and control takes the corrective actions needed to meet objectives."},{"text":"Test planning","correct":false,"why":"Planning defines objectives and the approach up front, but does not track ongoing progress."},{"text":"Test completion","correct":false,"why":"Completion collects data from finished activities and reports results at the end, rather than steering progress during the work."},{"text":"Test design","correct":false,"why":"Design creates test cases and test data from the test conditions; it is not a progress-tracking activity."}]$J$::jsonb, $L$In the test process, test monitoring gathers information to assess progress against the plan using metrics and exit criteria, while test control directs corrective actions. Together they keep testing aligned with its objectives.$L$, $L$A test lead notices the daily pass rate for the checkout module is falling behind the plan and reallocates two testers to that area, an example of monitoring and control.$L$
