insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m1-12$L$, $L$Fundamentals of Testing$L$, 1, $L$K2$L$, null, null, $L$During which test activity are test conditions defined by analyzing the test basis to identify what should be tested?$L$, $J$[{"text":"Test analysis","correct":true,"why":"Test analysis examines the test basis to determine testable features and define test conditions (the what to test)."},{"text":"Test design","correct":false,"why":"Design turns those conditions into concrete test cases and data (the how), which happens after analysis."},{"text":"Test implementation","correct":false,"why":"Implementation prepares testware such as test procedures and environments, after design."},{"text":"Test execution","correct":false,"why":"Execution runs the tests and compares actual to expected results, well after conditions are identified."}]$J$::jsonb, $L$Test analysis evaluates the test basis (such as requirements or user stories) to identify testable features and establish test conditions, answering what to test. This is distinct from test design, which specifies how to test by creating test cases.$L$, $L$Reading a user story for a password-reset feature, a tester derives test conditions such as expired reset links and reused passwords before writing any concrete test cases.$L$
