insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m1-13$L$, $L$Fundamentals of Testing$L$, 1, $L$K2$L$, null, null, $L$Which pair correctly matches a test activity to its primary output?$L$, $J$[{"text":"Test design produces test cases; test implementation produces test procedures and test data readiness","correct":true,"why":"Design yields test cases from conditions, while implementation organizes them into executable procedures and prepares the environment and data."},{"text":"Test analysis produces the final test summary report","correct":false,"why":"The test summary report is an output of test completion, not analysis."},{"text":"Test execution produces the test plan","correct":false,"why":"The test plan is produced during planning; execution produces test results and incident reports."},{"text":"Test planning produces defect fixes","correct":false,"why":"Defect fixes come from debugging by developers, not from the planning activity."}]$J$::jsonb, $L$In the test process, test design creates test cases and coverage items from test conditions, and test implementation prepares the testware needed to run them, including test procedures, test suites, and a ready test environment. Each activity has characteristic work products.$L$, $L$For a mobile wallet, testers design cases for insufficient-balance transfers, then implement them into an automated suite with seeded test accounts and a staging environment.$L$
from public.courses c where c.slug = 'istqb-foundation-masterclass'
