insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m4-03$L$, $L$Test Analysis & Design Techniques$L$, 4, $L$K2$L$, null, null, $L$Which is a genuine benefit of white-box testing that black-box testing cannot provide?$L$, $J$[{"text":"It can reveal code that is never executed by the black-box tests, such as unreachable or untested branches.","correct":true,"why":"Structural coverage measurement exposes code the specification-based tests never reach."},{"text":"It guarantees the software meets all user requirements.","correct":false,"why":"Full structural coverage says nothing about whether requirements are correct or complete."},{"text":"It removes the need for any specification-based tests.","correct":false,"why":"White-box and black-box are complementary; structural coverage does not check specified behaviour."},{"text":"It always finds more defects than any black-box technique.","correct":false,"why":"There is no such guarantee; the techniques find different classes of defect."}]$J$::jsonb, $L$White-box testing measures how much of the code structure has been exercised, so it can find gaps (untested statements or branches) that black-box tests, which only follow the specification, may leave unexecuted.$L$, $L$After a suite of requirement-based tests passes, a developer runs coverage tooling and finds an error-handling branch at 0% coverage, revealing a path the specification-based tests never triggered.$L$
