-- Module 7: Defect Management (25)
insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m7-01$L$, $L$Defect Management$L$, 7, $L$K1$L$, null, null, $L$In the ISTQB defect management process, what is the FIRST step once a possible defect (anomaly) has been recognised during testing?$L$, $J$[{"text":"The anomaly is logged and analysed to confirm whether it is a genuine defect","correct":true,"why":"ISTQB describes the process starting with logging/recognising the anomaly and then analysing it to determine if it is a true defect, a duplicate, or a non-defect (for example a test error)."},{"text":"The defect is immediately assigned to a developer to fix","correct":false,"why":"Assignment for fixing happens later, only after the anomaly has been confirmed as a real defect and classified; jumping straight to a fix skips confirmation and analysis."},{"text":"The defect is closed once the tester agrees it is minor","correct":false,"why":"Closing is the final state of the lifecycle, not the first step, and severity does not determine whether a defect is logged at all."},{"text":"A root cause analysis report is published to all stakeholders","correct":false,"why":"Root cause analysis and metrics reporting are downstream activities; the immediate first step is to record and analyse the individual anomaly."}]$J$::jsonb, $L$The ISTQB defect management process begins when an anomaly is recognised. It is logged, then analysed and classified to confirm it is a genuine defect (rather than a duplicate, environment issue, or test-design error) before any decision on fixing is made.$L$, $L$A tester on an e-commerce project sees a wrong VAT total at checkout. Before pinging a developer, they raise a defect ticket capturing the steps and expected/actual results, so a triage lead can confirm it is a real defect and not a mis-configured test environment.$L$
