select c.id, $L$m8-06$L$, $L$Risk-Based Testing$L$, 8, $L$K1$L$, null, null, $L$What is a product risk (also called a quality risk)?$L$, $J$[{"text":"A risk that the product may fail to satisfy some reasonable expectation of quality","correct":true,"why":"Product risks are potential problems with the quality of the product, e.g. failures, missing features, poor performance or security."},{"text":"A risk that the project will run out of budget before release","correct":false,"why":"Budget overrun is a project risk about managing the project, not a quality attribute of the product."},{"text":"A risk that a stakeholder will not attend the review meeting","correct":false,"why":"Attendance is an organisational project risk, not a product quality risk."},{"text":"A risk that the test tool licence will expire","correct":false,"why":"Tooling and licensing are project/technical risks, not risks about the product's quality."}]$J$::jsonb, $L$Product (quality) risks are directly related to the test object. They are the possibility that the software fails to meet expectations for functionality, reliability, performance, security, usability and other quality characteristics.$L$, $L$A slow search response under peak load is logged as a performance product risk, prompting the team to plan load tests before go-live.$L$
