insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m9-11$L$, $L$Test Tools$L$, 9, $L$K2$L$, null, null, $L$Which of the following is a well-recognised RISK of test automation according to ISTQB?$L$, $J$[{"text":"The ongoing cost of maintaining automated tests can be underestimated","correct":true,"why":"Maintenance effort - updating scripts as the software changes - is a major and frequently underestimated cost of automation."},{"text":"Automated tests never need to change once written","correct":false,"why":"That is false; changing software forces automated tests to be updated, which is the source of maintenance cost."},{"text":"Automation always costs nothing to set up","correct":false,"why":"Setting up automation requires real up-front investment in tools, frameworks and skills."},{"text":"Automation removes all reliance on tester skill","correct":false,"why":"Automation increases, rather than removes, the need for skilled people to build and maintain it."}]$J$::jsonb, $L$Key automation risks include underestimated maintenance cost, unrealistic expectations, over-reliance on automation at the expense of human testing, up-front setup effort, and dependence on the tool vendor. Maintenance is often the one that quietly sinks automation initiatives.$L$, $L$A team automates 800 UI tests, then a redesign changes every screen. Suddenly hundreds of tests fail and must be rewritten. The maintenance burden consumes more effort than the manual testing ever did - a cost nobody had budgeted for.$L$
