insert into public.practice_questions
  (course_id, ext_key, syllabus_topic, module_number, k_level, mock, mock_order, question_text, options, explanation, workplace_example)
select c.id, $L$m11-05$L$, $L$Real World QA$L$, 11, $L$K3$L$, null, null, $L$You are testing a new subscription pricing field that accepts a whole number of seats from 1 to 100. Time is tight. Which technique gives strong defect-finding coverage of this input with the fewest cases?$L$, $J$[{"text":"Boundary value analysis around 0/1 and 100/101, combined with equivalence partitioning for a valid mid-range value","correct":true,"why":"Defects cluster at boundaries; testing just inside and just outside each edge plus one representative valid value covers the likely failure points efficiently."},{"text":"Test every integer from 1 to 100 to be certain","correct":false,"why":"This approaches exhaustive testing for the field, adding little value over boundary and partition cases while wasting scarce time."},{"text":"Pick three random numbers and move on","correct":false,"why":"Random values may all fall inside one partition and miss the boundaries where defects concentrate."},{"text":"Use a state transition diagram of the pricing field","correct":false,"why":"A single numeric input field has no meaningful states to transition between; state transition testing fits event-driven behaviour, not this range check."}]$J$::jsonb, $L$Equivalence partitioning divides inputs into classes expected to behave the same, so one value per class suffices. Boundary value analysis targets the edges of those classes, where off-by-one and comparison-operator defects concentrate. Together they give high coverage of a bounded numeric field with a handful of cases, ideal under time pressure.$L$, $L$Age fields, quantity fields, and date ranges are the everyday home of boundary defects: '>=' written as '>', or a max of 100 that actually rejects 100. Testing 0, 1, 100, and 101 plus one middle value finds these in minutes, where testing all 100 values would find nothing extra.$L$
